#!/usr/bin/env bash
#
# Builds the single-file scripts in dist/ from db/.
#
# db/00_run_all.sql pulls in 01-14 with SQLCMD's :r, which means it will only run under
# sqlcmd, or under SSMS with SQLCMD mode switched on. People open a .sql file in SSMS and
# press F5; when that fails on a colon they conclude the script is broken.
#
# So the same content is also shipped flattened: one file, no directives, F5 works.
#
# GENERATED. Do not edit dist/ by hand — a copy that drifts from its source is worse than
# no copy. Run this instead.
#
set -euo pipefail

REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$REPO_ROOT"
mkdir -p dist

banner() {
    cat <<EOF
/* =====================================================================================
   $1
   -------------------------------------------------------------------------------------
   GENERATED by build/flatten.sh from $2. Do not edit this file: edit the source
   and run the generator again.

   Run it with whichever you prefer — it needs no SQLCMD mode and no command-line flags:

       In SSMS:  open this file, pick DB02 in the database dropdown, press F5.
       From a shell:
                 sqlcmd -S <server> -d DB02 -E -b -i $3

   It is idempotent. Running it twice over the same database is the normal case: that is
   how an upgrade is applied.

$4
   ===================================================================================== */
EOF
}

# ---- the schema, the engine and the reference data ------------------------------------

OUT="dist/maseera-schema.sql"

banner "Maseera — the whole schema, the engine and the reference data" \
       "db/00_run_all.sql and db/01-14" \
       "dist\\maseera-schema.sql" \
"   It creates nothing outside the database it is run against, and reads nothing from
   anywhere else. There is one database and its name is DB02.

   The receipt at the end is the check: every Configuration and Reference count must be
   non-zero. It raises an error if one is not." > "$OUT"

{
    cat <<'PREAMBLE'

/* These two are set here rather than left to the client, because the two clients
   disagree. SSMS connects with QUOTED_IDENTIFIER ON; sqlcmd connects with it OFF unless
   it is given -I. A filtered index cannot be created with it off, so without this the
   same file works in SSMS and fails halfway through from a command line — which is a
   miserable thing to debug. They persist for the session, so setting them once is enough,
   and every procedure below is created under them. */
SET QUOTED_IDENTIFIER ON;
SET ANSI_NULLS ON;
SET NOCOUNT ON;
GO

/* There is one database and its name is DB02. NOEXEC rather than a fatal error: it stops
   the rest of the file from running whichever client is used, and needs no special rights
   to do it. */
IF DB_NAME() <> N'DB02'
BEGIN
    RAISERROR(N'This script expects DB02. Pick DB02 in the database dropdown, or pass -d DB02.', 16, 1);
    SET NOEXEC ON;
END;
GO

PREAMBLE

    # 00_run_all.sql, with each :r replaced by the file it names and the SQLCMD-only
    # directives dropped.
    while IFS= read -r line; do
        case "$line" in
            ":on error exit")
                echo "/* :on error exit — a SQLCMD directive, and not available when this runs in SSMS."
                echo "   The receipt at the end is what catches a failed run instead. */"
                ;;
            ":r "*)
                file="db/${line#:r }"
                file="${file%$'\r'}"
                echo ""
                echo "/* ---- $(basename "$file") ------------------------------------------------------- */"
                echo ""
                cat "$file"
                echo ""
                ;;
            *)
                printf '%s\n' "$line"
                ;;
        esac
    done < db/00_run_all.sql

    echo ""
    echo "/* Leave the session usable whether or not the guard above fired. */"
    echo "SET NOEXEC OFF;"
    echo "GO"
} >> "$OUT"

# ---- the development fixture -----------------------------------------------------------

OUT="dist/maseera-demo-data.sql"

banner "Maseera — the development fixture" \
       "db/dev/01_mock_sources.sql and db/dev/02_demo_content.sql" \
       "dist\\maseera-demo-data.sql" \
"   DEVELOPMENT ONLY. Run dist\\maseera-schema.sql first.

   It CREATES AND FILLS the dbo.* tables the application reads — the roster, the course
   completions, the assessments, the coverage. If a real server already holds data in
   tables by those names, this will drop and replace it. Do not run it there.

   On a scratch database it gives you 624 invented people across a 37-unit organisation
   tree, a development framework, and an open talent-review cycle with 398 in the pool —
   loaded and configured entirely through the same procedures the screens call." > "$OUT"

{
    cat <<'PREAMBLE'

/* As in the schema file: SSMS and sqlcmd disagree about QUOTED_IDENTIFIER, and the
   scripts below build indexes and call procedures that were created under it. */
SET QUOTED_IDENTIFIER ON;
SET ANSI_NULLS ON;
SET NOCOUNT ON;
GO

PREAMBLE
    cat db/dev/01_mock_sources.sql
    echo
    echo "/* ---- 02_demo_content.sql ---------------------------------------------------- */"
    echo
    cat db/dev/02_demo_content.sql
    echo ""
    echo "SET NOEXEC OFF;"
    echo "GO"
} >> "$OUT"

# ---- what came out ---------------------------------------------------------------------

for f in dist/maseera-schema.sql dist/maseera-demo-data.sql; do
    printf '%-34s %8s lines  %6s\n' "$f" "$(wc -l < "$f")" "$(du -h "$f" | cut -f1)"
done

if grep -nE '^\s*:' dist/*.sql; then
    echo "A SQLCMD directive survived into dist/. That file will not run in SSMS." >&2
    exit 1
fi

echo "No SQLCMD directives remain."
